import{_ as s,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const p="/img/calc-distributive.svg",x=JSON.parse('{"title":"奥数精讲：巧算与速算三（四年级）","description":"深度解析四年级乘除法巧算技巧，通过分配律、结合律以及特殊数凑整法，让计算变得简单有趣。","frontmatter":{"title":"奥数精讲：巧算与速算三（四年级）","date":"2026-02-28T10:00:00.000Z","categories":["数学"],"tags":["四年级","巧算速算","乘除法"],"description":"深度解析四年级乘除法巧算技巧，通过分配律、结合律以及特殊数凑整法，让计算变得简单有趣。"},"headers":[],"relativePath":"posts/primary-math-olympiad-calc-3.md","filePath":"posts/primary-math-olympiad-calc-3.md","lastUpdated":null}'),l={name:"posts/primary-math-olympiad-calc-3.md"};function o(r,a,e,c,i,h){return n(),m("div",null,[...a[0]||(a[0]=[t('<h1 id="巧算与速算三-乘除法的艺术" tabindex="-1">巧算与速算三：乘除法的艺术 <a class="header-anchor" href="#巧算与速算三-乘除法的艺术" aria-label="Permalink to &quot;巧算与速算三：乘除法的艺术&quot;">​</a></h1><p>在四年级的数学学习中，计算量开始增大。如果只是硬算，不仅容易出错，还会浪费大量时间。学会“巧算”，本质上是学会观察数字之间的特征，利用运算律将复杂的计算转化为简单的计算。</p><h2 id="一、-核心知识点-乘法分配律" tabindex="-1">一、 核心知识点：乘法分配律 <a class="header-anchor" href="#一、-核心知识点-乘法分配律" aria-label="Permalink to &quot;一、 核心知识点：乘法分配律&quot;">​</a></h2><p>乘法分配律是巧算中最常用的武器。它的公式是：</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>a</mi><mo>×</mo><mo>(</mo><mi>b</mi><mo>+</mo><mi>c</mi><mo>)</mo><mo>=</mo><mi>a</mi><mo>×</mo><mi>b</mi><mo>+</mo><mi>a</mi><mo>×</mo><mi>c</mi></mrow><annotation encoding="application/x-tex">a \\times (b + c) = a \\times b + a \\times c </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord mathit">a</span><span class="mbin">×</span><span class="mopen">(</span><span class="mord mathit">b</span><span class="mbin">+</span><span class="mord mathit">c</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathit">a</span><span class="mbin">×</span><span class="mord mathit">b</span><span class="mbin">+</span><span class="mord mathit">a</span><span class="mbin">×</span><span class="mord mathit">c</span></span></span></span></span></p><p>或者</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>a</mi><mo>×</mo><mo>(</mo><mi>b</mi><mo>−</mo><mi>c</mi><mo>)</mo><mo>=</mo><mi>a</mi><mo>×</mo><mi>b</mi><mo>−</mo><mi>a</mi><mo>×</mo><mi>c</mi></mrow><annotation encoding="application/x-tex">a \\times (b - c) = a \\times b - a \\times c </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord mathit">a</span><span class="mbin">×</span><span class="mopen">(</span><span class="mord mathit">b</span><span class="mbin">−</span><span class="mord mathit">c</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathit">a</span><span class="mbin">×</span><span class="mord mathit">b</span><span class="mbin">−</span><span class="mord mathit">a</span><span class="mbin">×</span><span class="mord mathit">c</span></span></span></span></span></p><h3 id="【示例-1】利用分配律简化计算" tabindex="-1">【示例 1】利用分配律简化计算 <a class="header-anchor" href="#【示例-1】利用分配律简化计算" aria-label="Permalink to &quot;【示例 1】利用分配律简化计算&quot;">​</a></h3><p><strong>题目：</strong> 计算 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>5</mn><mo>×</mo><mn>1</mn><mn>0</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">25 \\times 104</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">4</span></span></span></span></p><h4 id="方法一-图示拆分法" tabindex="-1">方法一：图示拆分法 <a class="header-anchor" href="#方法一-图示拆分法" aria-label="Permalink to &quot;方法一：图示拆分法&quot;">​</a></h4><p>我们将 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">104</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">4</span></span></span></span> 拆成 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>0</mn><mo>+</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">100 + 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">4</span></span></span></span>，这样 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">25</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">5</span></span></span></span> 分别乘以这两个数都会得到非常整的数字。</p><p><img src="'+p+'" alt="乘法分配律步骤图"></p><p><strong>步骤详解：</strong></p><ol><li><strong>观察：</strong> 发现 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">104</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">4</span></span></span></span> 非常接近整百数 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>。</li><li><strong>拆分：</strong> 把 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">104</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">4</span></span></span></span> 写成 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>+</mo><mn>4</mn><mo>)</mo></mrow><annotation encoding="application/x-tex">(100 + 4)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mclose">)</span></span></span></span>。</li><li><strong>分配：</strong> 原式变为 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>5</mn><mo>×</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>+</mo><mn>2</mn><mn>5</mn><mo>×</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">25 \\times 100 + 25 \\times 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">4</span></span></span></span>。</li><li><strong>速算：</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>5</mn><mn>0</mn><mn>0</mn><mo>+</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>=</mo><mn>2</mn><mn>6</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">2500 + 100 = 2600</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">6</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>。</li></ol><h4 id="方法二-凑整结合法" tabindex="-1">方法二：凑整结合法 <a class="header-anchor" href="#方法二-凑整结合法" aria-label="Permalink to &quot;方法二：凑整结合法&quot;">​</a></h4><p>如果题目是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>5</mn><mo>×</mo><mn>3</mn><mn>2</mn><mo>×</mo><mn>1</mn><mn>2</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">25 \\times 32 \\times 125</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span></span></span></span>，我们可以观察到 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>5</mn><mo>×</mo><mn>4</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">25 \\times 4 = 100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mn>5</mn><mo>×</mo><mn>8</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">125 \\times 8 = 1000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">8</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>。</p><ol><li><strong>拆分：</strong> 将 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">32</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">2</span></span></span></span> 拆成 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mo>×</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">4 \\times 8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">8</span></span></span></span>。</li><li><strong>重组：</strong> 原式变为 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>2</mn><mn>5</mn><mo>×</mo><mn>4</mn><mo>)</mo><mo>×</mo><mo>(</mo><mn>1</mn><mn>2</mn><mn>5</mn><mo>×</mo><mn>8</mn><mo>)</mo></mrow><annotation encoding="application/x-tex">(25 \\times 4) \\times (125 \\times 8)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mclose">)</span><span class="mbin">×</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">8</span><span class="mclose">)</span></span></span></span>。</li><li><strong>计算：</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>0</mn><mo>×</mo><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo separator="true">,</mo><mn>0</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">100 \\times 1000 = 100,000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.8388800000000001em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mpunct">,</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>。</li></ol><hr><h2 id="二、-引导性思考-如何发现-巧算点" tabindex="-1">二、 引导性思考：如何发现“巧算点”？ <a class="header-anchor" href="#二、-引导性思考-如何发现-巧算点" aria-label="Permalink to &quot;二、 引导性思考：如何发现“巧算点”？&quot;">​</a></h2><p>解决同类问题时，请先问自己三个问题：</p><ol><li><strong>有没有接近整十、整百、整千的数？</strong>（如 99, 101, 251 等）</li><li><strong>有没有可以凑成整十、整百的“好朋友”对子？</strong><ul><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>×</mo><mn>5</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">2 \\times 5 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span></li><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mo>×</mo><mn>2</mn><mn>5</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">4 \\times 25 = 100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span></li><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mo>×</mo><mn>1</mn><mn>2</mn><mn>5</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">8 \\times 125 = 1000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span></li></ul></li><li><strong>有没有相同的因数可以提取？</strong>（逆用分配律） <ul><li>如 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>7</mn><mo>×</mo><mn>6</mn><mn>4</mn><mo>+</mo><mn>3</mn><mn>7</mn><mo>×</mo><mn>3</mn><mn>6</mn><mo>=</mo><mn>3</mn><mn>7</mn><mo>×</mo><mo>(</mo><mn>6</mn><mn>4</mn><mo>+</mo><mn>3</mn><mn>6</mn><mo>)</mo><mo>=</mo><mn>3</mn><mn>7</mn><mo>×</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>=</mo><mn>3</mn><mn>7</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">37 \\times 64 + 37 \\times 36 = 37 \\times (64 + 36) = 37 \\times 100 = 3700</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">7</span><span class="mbin">×</span><span class="mord mathrm">6</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mord mathrm">7</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">7</span><span class="mbin">×</span><span class="mopen">(</span><span class="mord mathrm">6</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">7</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">7</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>。</li></ul></li></ol><hr><h2 id="三、-引申思考-除法也有分配律吗" tabindex="-1">三、 引申思考：除法也有分配律吗？ <a class="header-anchor" href="#三、-引申思考-除法也有分配律吗" aria-label="Permalink to &quot;三、 引申思考：除法也有分配律吗？&quot;">​</a></h2><p>这是一个非常值得探讨的问题。</p><ul><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mi>a</mi><mo>+</mo><mi>b</mi><mo>)</mo><mo>÷</mo><mi>c</mi><mo>=</mo><mi>a</mi><mo>÷</mo><mi>c</mi><mo>+</mo><mi>b</mi><mo>÷</mo><mi>c</mi></mrow><annotation encoding="application/x-tex">(a + b) \\div c = a \\div c + b \\div c</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathit">a</span><span class="mbin">+</span><span class="mord mathit">b</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mord mathit">c</span><span class="mrel">=</span><span class="mord mathit">a</span><span class="mbin">÷</span><span class="mord mathit">c</span><span class="mbin">+</span><span class="mord mathit">b</span><span class="mbin">÷</span><span class="mord mathit">c</span></span></span></span> 是成立的（被除数分配）。</li><li>但是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>a</mi><mo>÷</mo><mo>(</mo><mi>b</mi><mo>+</mo><mi>c</mi><mo>)</mo></mrow><annotation encoding="application/x-tex">a \\div (b + c)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit">a</span><span class="mbin">÷</span><span class="mopen">(</span><span class="mord mathit">b</span><span class="mbin">+</span><span class="mord mathit">c</span><span class="mclose">)</span></span></span></span> <strong>绝对不等于</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>a</mi><mo>÷</mo><mi>b</mi><mo>+</mo><mi>a</mi><mo>÷</mo><mi>c</mi></mrow><annotation encoding="application/x-tex">a \\div b + a \\div c</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.77777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit">a</span><span class="mbin">÷</span><span class="mord mathit">b</span><span class="mbin">+</span><span class="mord mathit">a</span><span class="mbin">÷</span><span class="mord mathit">c</span></span></span></span>！</li></ul><p><strong>例如：</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>+</mo><mn>2</mn><mn>0</mn><mo>)</mo><mo>÷</mo><mn>5</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>÷</mo><mn>5</mn><mo>+</mo><mn>2</mn><mn>0</mn><mo>÷</mo><mn>5</mn><mo>=</mo><mn>2</mn><mn>0</mn><mo>+</mo><mn>4</mn><mo>=</mo><mn>2</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">(100 + 20) \\div 5 = 100 \\div 5 + 20 \\div 5 = 20 + 4 = 24</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">4</span></span></span></span>。正确。 <strong>注意：</strong> 只有被除数可以拆分，除数不能随意拆分分配。</p><hr><h2 id="四、-举一反三-实战练习" tabindex="-1">四、 举一反三：实战练习 <a class="header-anchor" href="#四、-举一反三-实战练习" aria-label="Permalink to &quot;四、 举一反三：实战练习&quot;">​</a></h2><p>请尝试用今天学到的巧算方法解决以下题目：</p><ol><li><p><strong>基础练习：</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mn>5</mn><mo>×</mo><mn>8</mn><mn>8</mn></mrow><annotation encoding="application/x-tex">125 \\times 88</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">8</span><span class="mord mathrm">8</span></span></span></span><em>提示：将 88 拆分为 80 + 8 或 8 × 11。</em></p></li><li><p><strong>进阶练习：</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mn>9</mn><mo>×</mo><mn>3</mn><mn>7</mn><mo>+</mo><mn>3</mn><mn>7</mn></mrow><annotation encoding="application/x-tex">99 \\times 37 + 37</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mord mathrm">7</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mord mathrm">7</span></span></span></span><em>提示：想一想 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>7</mn></mrow><annotation encoding="application/x-tex">37</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">7</span></span></span></span> 可以看作 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>7</mn><mo>×</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">37 \\times 1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">7</span><span class="mbin">×</span><span class="mord mathrm">1</span></span></span></span> 吗？提取公因数试试。</em></p></li><li><p><strong>挑战练习：</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>5</mn><mo>×</mo><mn>4</mn><mn>8</mn><mo>×</mo><mn>1</mn><mn>2</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">25 \\times 48 \\times 125</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mord mathrm">8</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span></span></span></span><em>提示：利用“好朋友”对子，将 48 拆开。</em></p></li></ol><hr><p><strong>解析预览：</strong></p><ol><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mn>5</mn><mo>×</mo><mo>(</mo><mn>8</mn><mn>0</mn><mo>+</mo><mn>8</mn><mo>)</mo><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>+</mo><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>=</mo><mn>1</mn><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">125 \\times (80 + 8) = 10000 + 1000 = 11000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mopen">(</span><span class="mord mathrm">8</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">8</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>。</li><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>9</mn><mn>9</mn><mo>+</mo><mn>1</mn><mo>)</mo><mo>×</mo><mn>3</mn><mn>7</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>×</mo><mn>3</mn><mn>7</mn><mo>=</mo><mn>3</mn><mn>7</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">(99 + 1) \\times 37 = 100 \\times 37 = 3700</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mord mathrm">7</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mord mathrm">7</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">7</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>。</li><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>2</mn><mn>5</mn><mo>×</mo><mn>4</mn><mo>)</mo><mo>×</mo><mo>(</mo><mn>1</mn><mn>2</mn><mn>5</mn><mo>×</mo><mn>8</mn><mo>)</mo><mo>×</mo><mo>(</mo><mn>4</mn><mn>8</mn><mo>÷</mo><mn>4</mn><mo>÷</mo><mn>8</mn><mo>)</mo></mrow><annotation encoding="application/x-tex">(25 \\times 4) \\times (125 \\times 8) \\times (48 \\div 4 \\div 8)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mclose">)</span><span class="mbin">×</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">8</span><span class="mclose">)</span><span class="mbin">×</span><span class="mopen">(</span><span class="mord mathrm">4</span><span class="mord mathrm">8</span><span class="mbin">÷</span><span class="mord mathrm">4</span><span class="mbin">÷</span><span class="mord mathrm">8</span><span class="mclose">)</span></span></span></span> ... 哎呀， <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>8</mn><mo>=</mo><mn>4</mn><mo>×</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">48 = 4 \\times 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">8</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span>，或者 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mo>×</mo><mn>6</mn><mo>×</mo><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi></mrow><annotation encoding="application/x-tex">4 \\times 6 \\times ...</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">6</span><span class="mbin">×</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span></span></span></span> 最简单是： <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>5</mn><mo>×</mo><mn>4</mn><mo>×</mo><mn>1</mn><mn>2</mn><mn>5</mn><mo>×</mo><mn>8</mn><mo>×</mo><mo>(</mo><mn>4</mn><mn>8</mn><mo>÷</mo><mn>3</mn><mn>2</mn><mo>)</mo><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>×</mo><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>×</mo><mn>1</mn><mi mathvariant="normal">.</mi><mn>5</mn><mo>=</mo><mn>1</mn><mn>5</mn><mn>0</mn><mo separator="true">,</mo><mn>0</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">25 \\times 4 \\times 125 \\times 8 \\times (48 \\div 32) = 100 \\times 1000 \\times 1.5 = 150,000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">8</span><span class="mbin">×</span><span class="mopen">(</span><span class="mord mathrm">4</span><span class="mord mathrm">8</span><span class="mbin">÷</span><span class="mord mathrm">3</span><span class="mord mathrm">2</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">.</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mpunct">,</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>。 或者： <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>5</mn><mo>×</mo><mo>(</mo><mn>4</mn><mo>×</mo><mn>2</mn><mo>)</mo><mo>×</mo><mn>6</mn><mo>×</mo><mn>1</mn><mn>2</mn><mn>5</mn><mo>=</mo><mo>(</mo><mn>2</mn><mn>5</mn><mo>×</mo><mn>4</mn><mo>)</mo><mo>×</mo><mo>(</mo><mn>1</mn><mn>2</mn><mn>5</mn><mo>×</mo><mn>8</mn><mo>)</mo><mo>×</mo><mn>6</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>×</mo><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>×</mo><mn>6</mn><mo>=</mo><mn>6</mn><mn>0</mn><mn>0</mn><mo separator="true">,</mo><mn>0</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">25 \\times (4 \\times 2) \\times 6 \\times 125 = (25 \\times 4) \\times (125 \\times 8) \\times 6 = 100 \\times 1000 \\times 6 = 600,000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mopen">(</span><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mclose">)</span><span class="mbin">×</span><span class="mord mathrm">6</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mclose">)</span><span class="mbin">×</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">8</span><span class="mclose">)</span><span class="mbin">×</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">6</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mpunct">,</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>。 <em>(纠正：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>8</mn><mo>=</mo><mn>6</mn><mo>×</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">48 = 6 \\times 8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">8</span><span class="mrel">=</span><span class="mord mathrm">6</span><span class="mbin">×</span><span class="mord mathrm">8</span></span></span></span>，所以 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>5</mn><mo>×</mo><mn>6</mn><mo>×</mo><mo>(</mo><mn>8</mn><mo>×</mo><mn>1</mn><mn>2</mn><mn>5</mn><mo>)</mo><mo>=</mo><mn>1</mn><mn>5</mn><mn>0</mn><mo>×</mo><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>=</mo><mn>1</mn><mn>5</mn><mn>0</mn><mo separator="true">,</mo><mn>0</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">25 \\times 6 \\times (8 \\times 125) = 150 \\times 1000 = 150,000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">6</span><span class="mbin">×</span><span class="mopen">(</span><span class="mord mathrm">8</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mpunct">,</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>。)</em></li></ol>',33)])])}const b=s(l,[["render",o]]);export{x as __pageData,b as default};
